; bounce.asm -- chapter 11: a ball that turns round at every edge
; generated by gen11.py
        INCLUDE "msx.inc"
        OUTPUT "bounce.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
NAMES   EQU $1800               ; the name table: a byte for each cell
dx      EQU VARS + $10          ; the steps across and down, 1 or -1, and
dy      EQU VARS + $11          ; the count of turns: in the RAM, since the
bounces EQU VARS + $12          ; cartridge is ROM (chapter 8)
; A ball of one cell in the box of the screen, a step across and a step down
; at each move, turning back at every edge: 150 moves, each cell it
; passes made black (figure 11.2).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 7, LIGHT_GREEN  ; a border of another colour: the box shows
        VRAM_WRITE $0400        ; character 128: every pixel ink
        ld b, 8
        ld a, $FF
blk:    out (VDP_DATA), a
        djnz blk
        ld a, 1
        ld (dx), a
        ld (dy), a              ; down and to the right
        xor a
        ld (bounces), a
        ld d, 0                 ; D: the column, 0 to 31
        ld e, 0                 ; E: the row, 0 to 23
        ld b, 150
move:   push bc
        call plot               ; the ball's cell, black
        ld a, (dx)
        add a, d
        ld d, a                 ; a step across
        or a
        jr z, flipx             ; at the left edge ...
        cp 31
        jr nz, okx              ; ... or the right: turn round
flipx:  ld a, (dx)
        neg                     ; 1 becomes -1, -1 becomes 1
        ld (dx), a
        call count
okx:    ld a, (dy)
        add a, e
        ld e, a                 ; a step down
        or a
        jr z, flipy             ; at the top ...
        cp 23
        jr nz, oky              ; ... or the bottom: turn round
flipy:  ld a, (dy)
        neg
        ld (dy), a
        call count
oky:    pop bc
        djnz move
        call plot               ; where the ball stopped
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; plot: the cell at column D, row E made black. Uses A, BC, HL.
plot:   ld l, e
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; the row times 32
        ld a, l
        or d                    ; plus the column
        ld l, a
        ld bc, NAMES
        add hl, bc              ; HL: the cell in the name table
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40                  ; a write
        out (VDP_CTRL), a
        ld a, 128
        out (VDP_DATA), a       ; the black character
        ret

; count: one more turn
count:  ld hl, bounces
        inc (hl)
        ret

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
